def count_subsets(items, target, i=0):
    """Count subsets of items[i:] summing exactly to target."""
    if i == len(items):
        return 1 if target == 0 else 0
    return (count_subsets(items, target - items[i], i + 1)   # take items[i]
            + count_subsets(items, target, i + 1))           # skip items[i]

print(count_subsets([2, 4, 6, 10], 16))   # 2: {6, 10} and {2, 4, 10}

